                }
            }
        }
        keySerializer.serialize(keyElem, gen, provider);
        try {
            valueSer.serializeWithType(valueElem, gen, provider, _valueTypeSerializer);
        } catch (Exception e) {
            wrapAndThrow(provider, e, value, String.valueOf(keyElem));
        }
    }
